function CommonPreviewListNode:Refresh()
    if isNull(self.dialogData)
    or isNull(self.nodeData) then
        return
    end

    if isNotNull(self.dialogData.funcRequestGetOne) then
        local getState = self.nodeData.getState
        KTool.SetActive(self.RT_CanGetGroup, getState == Constants.GetStatus.Can)
        KTool.SetActive(self.RT_CannotGetGroup, getState == Constants.GetStatus.Not)
        KTool.SetActive(self.RT_AlreadyGetGroup, getState == Constants.GetStatus.Has)
    end
    
    CfUtils.FillText(self.Txt_Name, tostring(self.nodeData.name))

    if isNotNull(self.CommonGoodsListLight) then
        self.LT_GoodsList:FreshBaseUI(self.nodeData.rewardsList)
    end

    if isNotNull(self.Txt_Value) and isNotNull(self.nodeData.value) then
        
        CfUtils.FillText(self.Txt_Value, tostring(self.nodeData.value))
